package main

import (
	"context"
	"database/sql"
)

func userNames(ctx context.Context, db *sql.DB) ([]string, error) {
	rows, err := db.QueryContext(ctx, "SELECT name FROM users")
	if err != nil {
		return nil, err
	}
	defer rows.Close() // ALWAYS returns the connection, even on early return

	var names []string
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			return nil, err // safe now: deferred Close runs
		}
		names = append(names, n)
	}
	if err := rows.Err(); err != nil { // surface errors that ended iteration
		return nil, err
	}
	return names, nil
}

