package solution

import (
	"context"
	"database/sql"
	"errors"
)

var ErrInsufficientFunds = errors.New("insufficient funds")

func Transfer(ctx context.Context, db *sql.DB, from, to, amount int) error {
	tx, err := db.BeginTx(ctx, nil) // checks out one connection for the tx
	if err != nil {
		return err
	}
	defer tx.Rollback() // no-op after a successful Commit; safety net otherwise

	// Debit only if the balance can cover it; rows-affected tells us if it did.
	res, err := tx.ExecContext(ctx,
		"UPDATE accounts SET balance = balance - $1 WHERE id = $2 AND balance >= $1",
		amount, from)
	if err != nil {
		return err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 { // no row matched the balance>=amount guard
		return ErrInsufficientFunds
	}

	if _, err := tx.ExecContext(ctx,
		"UPDATE accounts SET balance = balance + $1 WHERE id = $2",
		amount, to); err != nil {
		return err
	}

	return tx.Commit() // both updates succeed atomically
}

