	if len(ids) == 0 {
		return nil, nil // nothing to query
	}
	rows, err := db.QueryContext(ctx,
		"SELECT name FROM users WHERE id = ANY($1)", pq.Array(ids))
	if err != nil {
		return nil, err
	}
	defer rows.Close() // always returns the connection to the pool

